const items = $input.all();
const results = items[0].json.results;

if (!results || results.length === 0) {
  return [{ json: { message: "No matching candidates found." } }];
}

const query = items[0].json.query || "N/A";

let message = `*Candidate Search Results*\n`;
message += `Query: _${query.substring(0, 100)}${query.length > 100 ? '...' : ''}_\n`;
message += `Found: *${results.length}* candidates (sorted by experience)\n\n`;

results.forEach((c, i) => {
  const issues = c.qualification_issues?.length > 0
    ? `Issues: ${c.qualification_issues.join(', ')}`
    : `No qualification issues`;

  const certs = c.licenses?.map(l => l.name).join(', ') || 'None';
  const skills = c.skills?.join(', ') || 'None';
  const langs = c.languages?.map(l => `${l.language} (${l.proficiency})`).join(', ') || 'N/A';

  // Professional Gmail compose URL
  if (c.email) {
    const subject = encodeURIComponent('Interview Invitation - ' + c.role_en + ' Position');
    const body = encodeURIComponent(
      'Dear ' + c.name + ',\n\n' +
      'Thank you for your interest in the ' + c.role_en + ' position at our company.\n\n' +
      'We would like to invite you for an interview to discuss this opportunity further.\n\n' +
      'Interview Details:\n' +
      '───────────────────\n' +
      'Position: ' + c.role_en + '\n' +
      'Date: [Please specify date]\n' +
      'Time: [Please specify time]\n' +
      'Duration: Approximately 60 minutes\n' +
      'Location: [Please specify location or meeting link]\n\n' +
      'Interview Format:\n' +
      'The interview will be conducted by our HR team and hiring manager. We will discuss your experience, skills, and how you might contribute to our team.\n\n' +
      'Please confirm your availability by replying to this email.\n\n' +
      'If you have any questions or need to reschedule, please do not hesitate to contact us.\n\n' +
      'We look forward to meeting you.\n\n' +
      'Best regards,\n' +
      'HR Department\n' +
      '[Your Company Name]\n' +
      '[Contact Email]\n' +
      '[Phone Number]'
    );
    var gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${c.email}&su=${subject}&body=${body}`;
  }

  message += `─────────────────────────────\n`;
  message += `*${i + 1}. ${c.name}* - ${c.role_en} (${c.role})\n`;
  message += `Experience: *${c.experience_years} years* | Match Score: *${c.match_score}%*\n\n`;

  // Gmail compose link
  if (c.email) {
    message += `*Contact:*\n`;
    message += `<${gmailUrl}|Send Interview Invitation to ${c.email}>\n`;
    message += `_Click to compose professional interview email_\n\n`;
  } else {
    message += `Email: Not provided\n\n`;
  }

  if (c.phone) {
    message += `Phone: <tel:${c.phone}|${c.phone}>\n`;
  }

  message += `Salary: €${c.salary?.toLocaleString()}/month\n`;
  message += `Location: ${c.location?.city} (${c.location?.postal_code})\n`;
  message += `Availability: ${c.availability}\n`;
  message += `Education: ${c.education?.level} - ${c.education?.institution}\n`;
  message += `Skills: ${skills}\n`;
  message += `Licenses: ${certs}\n`;
  message += `Languages: ${langs}\n`;
  message += `TES: ${c.applicable_tes || 'N/A'}\n`;
  message += `Summary: _${c.summary || 'N/A'}_\n`;
  message += `${issues}\n`;
  message += `Analysis: _${c.explanation}_\n\n`;
});

message += `─────────────────────────────\n`;
message += `_Generated: ${new Date().toLocaleString('en-US', { timeZone: 'Europe/Helsinki' })}_`;

return [{ json: { message } }];
